<?php
declare(strict_types=1);
function people_schema(PDO $db): void {
 $db->exec("CREATE TABLE IF NOT EXISTS people_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);CREATE TABLE IF NOT EXISTS work_sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,username TEXT NOT NULL,token TEXT UNIQUE NOT NULL,started INTEGER NOT NULL,seen INTEGER NOT NULL,ended INTEGER,reason TEXT NOT NULL DEFAULT '',approved INTEGER NOT NULL DEFAULT 0);CREATE INDEX IF NOT EXISTS work_sessions_user ON work_sessions(user_id,started);CREATE TABLE IF NOT EXISTS work_adjustments(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,started INTEGER NOT NULL,ended INTEGER NOT NULL,approved INTEGER NOT NULL,note TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS people_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,username TEXT NOT NULL,display_name TEXT NOT NULL,event TEXT NOT NULL,target TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS people_audit_date ON people_audit(created_at,id)");
}
function people_require_owner(): void {if(!(team_identity()['owner']??false))throw new RuntimeException('Chỉ quản trị viên gốc được mở CÀI ĐẶT, chấm công và bảng lương của toàn bộ nhân viên.',403);}
function people_name($v): string {if(!is_string($v)||mb_strlen($v)>100||preg_match('/[\p{C}]/u',$v))throw new RuntimeException('Tên hiển thị tối đa 100 ký tự, không chứa ký tự điều khiển.',400);return trim($v);}
function people_audit(string $event,string $target,array $details=[],?PDO $db=null,?array $actor=null): void {
 $db??=team_db();people_schema($db);$actor??=team_identity()??['id'=>0,'username'=>'system','name'=>'Hệ thống'];
 $db->prepare('INSERT INTO people_audit(user_id,username,display_name,event,target,details,created_at) VALUES(?,?,?,?,?,?,?)')->execute([(int)$actor['id'],$actor['username'],$actor['name']?:$actor['username'],$event,$target,json_encode($details,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),gmdate('Y-m-d\TH:i:s\Z')]);
}
function people_setting(string $key,$default=null){$db=team_db();people_schema($db);$q=$db->prepare('SELECT value FROM people_settings WHERE key=?');$q->execute([$key]);$v=$q->fetchColumn();return $v===false?$default:json_decode($v,true,512,JSON_THROW_ON_ERROR);}
function people_set(string $key,$value): void {$db=team_db();people_schema($db);$db->prepare('INSERT INTO people_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value')->execute([$key,json_encode($value,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);}
function people_profile_save(array $data): array {
 $u=team_identity();if(!$u)throw new RuntimeException('Vui lòng đăng nhập.',401);$name=people_name($data['name']??'');$db=team_db();$db->beginTransaction();try{if($u['owner'])people_set('owner_name',$name);else $db->prepare('UPDATE staff SET name=? WHERE id=?')->execute([$name,$u['id']]);people_audit('profile','Hồ sơ cá nhân',['before'=>$u['name'],'after'=>$name]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}return team_identity();
}
function people_session_start(?int $now=null): void {
 $u=team_identity();if(!$u)return;$db=team_db();people_schema($db);$now??=time();$token=bin2hex(random_bytes(24));$db->beginTransaction();try{$db->prepare('INSERT INTO work_sessions(user_id,username,token,started,seen) VALUES(?,?,?,?,?)')->execute([$u['id'],$u['username'],$token,$now,$now]);people_audit('login','Đăng nhập',[],null,$u);$db->commit();$_SESSION['work_token']=$token;}catch(Throwable $e){$db->rollBack();throw $e;}
}
function people_session_touch(): void {
 if(!admin_logged_in())return;if(empty($_SESSION['work_token']))people_session_start();
}
function people_activity(array $data): void {
 $db=team_db();$q=$db->prepare('SELECT * FROM work_sessions WHERE token=?');$q->execute([$_SESSION['work_token']??'']);$s=$q->fetch();if(!$s)return;$now=time();$at=$data['at']??null;if(!is_int($at)||$at>$now+5||$at<$now-90)throw new RuntimeException('Thời điểm hoạt động không hợp lệ.',400);$at=min($at,$now);if($at<=(int)$s['seen'])return;$idle=people_setting('payroll_policy',[])['idle_minutes']??null;
 if($s['ended']!==null||($idle!==null&&$at-(int)$s['seen']>(int)$idle*60)){people_session_end('idle',(int)$s['seen']);people_session_start($at);return;}
 $db->prepare('UPDATE work_sessions SET seen=? WHERE id=? AND ended IS NULL')->execute([$at,$s['id']]);
}
function people_session_end(string $reason='logout',?int $end=null): void {
 if(empty($_SESSION['work_token']))return;$db=team_db();people_schema($db);$q=$db->prepare('SELECT * FROM work_sessions WHERE token=? AND ended IS NULL');$q->execute([$_SESSION['work_token']]);$row=$q->fetch();if(!$row)return;$idle=people_setting('payroll_policy',[])['idle_minutes']??null;if($reason!=='logout'||($idle!==null&&time()-(int)$row['seen']>(int)$idle*60))$end=(int)$row['seen'];$end=max((int)$row['started'],$end??time());$u=team_identity()??['id'=>(int)$row['user_id'],'username'=>$row['username'],'name'=>$row['username']];
 $db->beginTransaction();try{$db->prepare('UPDATE work_sessions SET ended=?,seen=?,reason=?,approved=? WHERE id=? AND ended IS NULL')->execute([$end,$end,$reason,in_array($reason,['logout','idle','expired'],true)?1:0,$row['id']]);people_audit($reason==='logout'?'logout':'session_end','Phiên #'.$row['id'],['reason'=>$reason,'started'=>(int)$row['started'],'ended'=>$end],null,$u);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}unset($_SESSION['work_token']);
}
function people_effective_sessions(int $id,int $from,int $to): array {
 $db=team_db();people_schema($db);$q=$db->prepare('SELECT s.*,a.started AS adjusted_start,a.ended AS adjusted_end,a.approved AS adjusted_approved,a.note AS adjustment_note,a.actor AS adjustment_actor FROM work_sessions s LEFT JOIN work_adjustments a ON a.id=(SELECT max(b.id) FROM work_adjustments b WHERE b.session_id=s.id) WHERE s.user_id=? AND COALESCE(a.started,s.started)<? AND (COALESCE(a.ended,s.ended) IS NULL OR COALESCE(a.ended,s.ended)>?) ORDER BY COALESCE(a.started,s.started)');$q->execute([$id,$to,$from]);$rows=$q->fetchAll();$idle=people_setting('payroll_policy',[])['idle_minutes']??null;foreach($rows as &$r){unset($r['token']);$r['effective_start']=(int)($r['adjusted_start']??$r['started']);$r['effective_end']=$r['adjusted_end']??$r['ended'];$r['effective_approved']=(int)($r['adjusted_approved']??$r['approved']);if($r['effective_end']===null&&$idle!==null&&time()-(int)$r['seen']>(int)$idle*60){$r['effective_end']=(int)$r['seen'];$r['effective_approved']=1;$r['auto_idle']=true;}$r['effective_end']=$r['effective_end']===null?null:(int)$r['effective_end'];}return $rows;
}
function people_adjust(array $data): void {
 people_require_owner();$id=filter_var($data['id']??null,FILTER_VALIDATE_INT);$start=people_local_time($data['started']??'');$end=people_local_time($data['ended']??'');$note=trim((string)($data['note']??''));$approved=$data['approved']??null;if(!$id||$end<=$start||$end-$start>48*3600||mb_strlen($note)<3||mb_strlen($note)>1000||!is_bool($approved))throw new RuntimeException('Cần thời gian hợp lệ (tối đa 48 giờ), lý do và trạng thái duyệt.',400);
 $db=team_db();$q=$db->prepare('SELECT * FROM work_sessions WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Không tìm thấy phiên làm việc.',404);if($old['ended']===null&&time()-(int)$old['seen']<=1800)throw new RuntimeException('Phiên vẫn đang mở. Nhân viên cần đăng xuất trước khi duyệt.',409);
 $db->beginTransaction();try{$db->prepare('INSERT INTO work_adjustments(session_id,started,ended,approved,note,actor,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$id,$start,$end,$approved?1:0,$note,team_identity()['username'],gmdate('c')]);people_audit('attendance_adjust','Phiên #'.$id,['before'=>$old,'started'=>$start,'ended'=>$end,'approved'=>$approved,'note'=>$note]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}
}
function people_local_time($s): int {if(!is_string($s))throw new RuntimeException('Thời gian không hợp lệ.',400);$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$s,new DateTimeZone('Asia/Ho_Chi_Minh'));if(!$d||$d->format('Y-m-d\TH:i')!==$s||$d->getTimestamp()>time()+60)throw new RuntimeException('Thời gian cần đúng định dạng và không ở tương lai.',400);return $d->getTimestamp();}
function people_month($s): array {if(!is_string($s)||!preg_match('/^20[0-9]{2}-(0[1-9]|1[0-2])$/D',$s))throw new RuntimeException('Tháng không hợp lệ.',400);$a=new DateTimeImmutable($s.'-01',new DateTimeZone('Asia/Ho_Chi_Minh'));return [$a->getTimestamp(),$a->modify('+1 month')->getTimestamp()];}
function people_audit_list(array $input): array {
 people_require_owner();$page=max(1,(int)($input['page']??1));$limit=50;$where=[];$args=[];
 foreach(['username','event'] as $key)if(($input[$key]??'')!==''){$where[]=$key.'=?';$args[]=(string)$input[$key];}
 foreach(['from','to'] as $key)if(($input[$key]??'')!==''){$s=(string)$input[$key];$d=DateTimeImmutable::createFromFormat('!Y-m-d',$s,new DateTimeZone('Asia/Ho_Chi_Minh'));if(!$d||$d->format('Y-m-d')!==$s)throw new RuntimeException('Ngày lọc không hợp lệ.',400);if($key==='to')$d=$d->modify('+1 day');$where[]='created_at'.($key==='from'?'>=':'<').'?';$args[]=$d->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z');}
 $a=team_db();people_schema($a);$a->exec("ATTACH DATABASE ".$a->quote(admin_private().'/orders.sqlite')." AS order_audit");try{$b=admin_db();people_schema($b);$sql=' FROM (SELECT *,\'auth\' AS source FROM main.people_audit UNION ALL SELECT *,\'orders\' AS source FROM order_audit.people_audit)'.($where?' WHERE '.implode(' AND ',$where):'');$q=$a->prepare('SELECT count(*)'.$sql);$q->execute($args);$total=(int)$q->fetchColumn();$page=min($page,max(1,(int)ceil($total/$limit)));$q=$a->prepare('SELECT *'.$sql.' ORDER BY created_at DESC,source,id DESC LIMIT '.$limit.' OFFSET '.(($page-1)*$limit));$q->execute($args);return ['rows'=>$q->fetchAll(),'total'=>$total,'page'=>$page,'pages'=>max(1,(int)ceil($total/$limit))];}finally{$a->exec('DETACH DATABASE order_audit');}
}
function people_cell(array $cell): array {unset($cell['custom']);if(!empty($cell['f']))unset($cell['v']);return $cell;}
function people_workbook_diff(?array $before,array $after): array {
 $changes=[];$before??=['sheets'=>[]];foreach(array_unique(array_merge(array_keys($before['sheets']??[]),array_keys($after['sheets']??[]))) as $id){$old=$before['sheets'][$id]??[];$new=$after['sheets'][$id]??[];$label=$new['name']??$old['name']??$id;
 if(!$old||!$new)$changes[]=['sheet'=>$label,'field'=>'Trang tính','before'=>$old?'Tồn tại':null,'after'=>$new?'Tồn tại':null];
 foreach(array_unique(array_merge(array_keys($old['cellData']??[]),array_keys($new['cellData']??[]))) as $r)foreach(array_unique(array_merge(array_keys($old['cellData'][$r]??[]),array_keys($new['cellData'][$r]??[]))) as $c){$a=people_cell($old['cellData'][$r][$c]??[]);$b=people_cell($new['cellData'][$r][$c]??[]);if($a!=$b){$col='';for($i=(int)$c+1;$i>0;$i=intdiv($i-1,26))$col=chr(65+($i-1)%26).$col;$changes[]=['sheet'=>$label,'cell'=>$col.((int)$r+1),'before'=>$a,'after'=>$b];}}
 unset($old['cellData'],$new['cellData']);foreach(array_unique(array_merge(array_keys($old),array_keys($new))) as $key)if(($old[$key]??null)!=($new[$key]??null))$changes[]=['sheet'=>$label,'field'=>$key,'before'=>$old[$key]??null,'after'=>$new[$key]??null];}
 foreach(array_unique(array_merge(array_keys($before),array_keys($after))) as $key)if($key!=='sheets'&&($before[$key]??null)!=($after[$key]??null))$changes[]=['field'=>$key,'before'=>$before[$key]??null,'after'=>$after[$key]??null];return $changes;
}
